/* ghost_teams.h -- ghost teams: sides made of players from all over the database
 * (src/ghost_teams.c; the teams, by reference, in src/ghost_teams_data.c, generated by
 * scripts/ghost_teams.py). Both targets.
 *
 * BEST XI, the most expensive club player at every position of a 4-4-2, is CHALLENGE
 * CUP's bonus match after the final (docs/CHALLENGE_CUP.md). */
#ifndef GHOST_TEAMS_H
#define GHOST_TEAMS_H

#include "game_types.h"

/* A ghost team's id: the custom teams' file (72, which has 48) and a number from 200, so no
 * team has it and the match finds it among the selected teams only. The file must be a real
 * one: screens look a team's country up by its file number (_countriesTable, 262 entries,
 * most of them empty -- a made-up number read a name through NULL on VIEW OPPO). */
#define GHOST_TEAM_FILE          72
#define GHOST_TEAM_FIRST_ORDINAL 200

/* One player: where he is in the database, and the names that are checked. */
typedef struct GhostPlayerRef {
    uint8_t     country;        /* his team's file, TEAM.nnn */
    uint8_t     ordinal;        /* his team's number in it */
    uint8_t     index;          /* his number in that team's player list */
    const char *team;
    const char *name;
} GhostPlayerRef;

typedef struct GhostTeam {
    const char    *name;
    const char    *coach;
    uint8_t        homeKit[5];  /* shirt type, stripes, basic, shorts, socks colours */
    uint8_t        awayKit[5];
    GhostPlayerRef players[16]; /* a 4-4-2's eleven in team-file order, then the bench */
} GhostTeam;

extern const GhostTeam g_ghostBestXI;

/* Builds the team into `out` (number GHOST_TEAM_FIRST_ORDINAL + `ordinal` of
 * GHOST_TEAM_FILE), its players copied
 * from their teams fresh -- no cards, injuries, goals or form -- and shirts 1..16 in order.
 * 0 = a player is not in this database (logged on SDL); `out` is then not a team. */
int32_t GhostTeams_Build(const GhostTeam *ghost, uint8_t ordinal, TeamFileEx *out);

/* 1 if `team` is a ghost team (by its id). */
int32_t GhostTeams_IsGhost(const TeamFileEx *team);

#endif /* GHOST_TEAMS_H */
